import type { Language } from '../i18n';
import data from './catalog.json';

export type LocalizedText = Record<Language, string>;

export interface CatalogCategory {
  id: string;
  title: LocalizedText;
}

export interface CatalogImage {
  id: string;
  category: string;
  title: LocalizedText;
  width: number;
  height: number;
  author: string;
  license: string;
  licenseUrl: string;
  /** Page describing the original (licence evidence). */
  sourcePage: string;
}

export interface Catalog {
  categories: CatalogCategory[];
  images: CatalogImage[];
}

/** Generated by `npm run images` (scripts/prepare-images.ts) from content/images.json. */
export const catalog = data as Catalog;

export function imagesIn(categoryId: string): CatalogImage[] {
  return catalog.images.filter((img) => img.category === categoryId);
}

export function findImage(id: string): CatalogImage | undefined {
  return catalog.images.find((img) => img.id === id);
}

export function findCategory(id: string): CatalogCategory | undefined {
  return catalog.categories.find((c) => c.id === id);
}

// Relative URLs so they work both on the web and inside the Capacitor WebView.
export const imageUrl = (id: string): string => `images/${id}.webp`;
export const thumbUrl = (id: string): string => `images/thumbs/${id}.webp`;

/** Decodes a catalogue picture into a bitmap suitable for cutting. */
export async function loadCatalogImage(id: string): Promise<ImageBitmap> {
  const res = await fetch(imageUrl(id));
  if (!res.ok) throw new Error(`Image ${id} could not be loaded (${res.status})`);
  return createImageBitmap(await res.blob());
}
